[DataContractAttribute]
public class TFMLogicBlocksContract
{
    Name            blockName;
    ClassName       className;
    str             resourcePath;
    str             purchReqStatus;
    str             classType;
    str             boxText;
    int             numberOfInputs;
    int             numberOfOutputs;
    str             editorName;
    List             categories;



}

Method.Source:
public void new()
{
    numberOfInputs = 1;
    numberOfOutputs= 1;

    editorName = 'editornameplaceholder';
    categories = new List(Types::String);
}

[DataMemberAttribute]
public Name parmBlockName(Name _blockName = blockName)
{
    blockName = _blockName;
    return blockName;
}

[DataMemberAttribute]
public ClassName parmClassName(ClassName _className = className)
{
    className = _className;
    return className;
}

[DataMemberAttribute]
public str parmResourcePath(str _resourcePath = resourcePath)
{
    resourcePath = _resourcePath;
    return resourcePath;
}

[DataMemberAttribute('ClassType')]
public str parmClassType(str _classType = classType)
{
    classType = _classType;
    return classType ? classType : 'LogicBlock';
}

[DataMemberAttribute('BoxText')]
public str parmBoxText(str _boxText = boxText)
{
    boxText = _boxText;
    return boxText;
}

[DataMemberAttribute('NumberOfInputs')]
public int parmNumberOfInputs(int _numberOfInputs = numberOfInputs)
{
    numberOfInputs = _numberOfInputs;
    return numberOfInputs;
}

[DataMemberAttribute('NumberOfOutputs')]
public int parmNumberOfOutputs(int _numberOfOutputs = numberOfOutputs)
{
    numberOfOutputs = _numberOfOutputs;
    return numberOfOutputs;
}

[DataMemberAttribute('editorName')]
public str parmEditorName(ClassName _editorName = editorName)
{
    editorName = _editorName;
    return editorName;
}

[DataMemberAttribute('categories')]
public List parmCategories(List _categories = categories)
{
    categories = _categories;
    return categories;
}
